// Demo: JTAG Boundary Scan — marching memory test
var mem=new Array(1).fill(0);var fails=0;
for(var i=0;i<mem.length;i++){mem[i]=1;}
for(var i=0;i<mem.length;i++){if(mem[i]!==1)fails++;mem[i]=0;}
console.log('technique: JTAG Boundary Scan');console.log('cells tested: '+mem.length+', failures: '+fails);
console.log(fails===0?'memory OK':'FAILURES — replace the module');

// Demo: POST Code Diagnosis — POST code sequence
var codes=[['0x01','CPU'],['0x2A','memory'],['0x55','PCI'],['0xA0','boot']];
var hang=(2%4);
console.log('technique: POST Code Diagnosis');
codes.forEach(function(c,i){console.log(c[0]+' '+c[1]+(i<=hang?' OK':' --'));;});
console.log('hang at '+codes[hang][0]+' -> suspect '+codes[hang][1]);

