// Demo: ECC Error Injection — CRC fault detection
function crc16(s){var c=0xFFFF;for(var i=0;i<s.length;i++){c^=s.charCodeAt(i);for(var b=0;b<8;b++){c=(c&1)?(c>>>1)^0xA001:c>>>1;}}return c;}
var good=crc16('frame-5');var bad=crc16('frame-5'.replace('e','f'));
console.log('technique: ECC Error Injection');console.log('good CRC: '+good.toString(16)+', corrupted CRC: '+bad.toString(16));
console.log(good!==bad?'single-bit-class corruption detected':'CRC MISSED IT');

